export async function note(gh: GitHub, repo: RepoRef, pr: number): Promise<void> {
  await gh.request("POST", `/repos/${repo.owner}/${repo.repo}/issues/${pr}/comments`, { body: "preparing" });
}

export async function clearTeam(gh: GitHub, path: string): Promise<void> {
  await gh.request<unknown>("DELETE", `${path}/requested_reviewers`, { team_reviewers: ["reviewer"] });
}

export async function resolve(gh: GitHub, thread: string): Promise<void> {
  await gh.graphql(`mutation($thread: ID!) { resolveReviewThread(input: { threadId: $thread }) { clientMutationId } }`, { thread });
}

